class Item { public int Value { get; init; } }
int Pair(int first, int second) => first * 10 + second;
class Maker {
    private int Value = 3;
    public Item Make() => new Item { Value = this.Value + Value };
}
void Main() {
    var n = 1;
    var a = new Item { Value = Pair(second: n++, first: ++n) }; Print(a.Value); Print(n);
    var b = new Maker().Make(); Print(b.Value);
    Print(false ? new Item { Value = ++n }.Value : n);
    var original = new Item { Value = 7 };
    original = new Item { Value = original.Value + 2 }; Print(original.Value);
}
